param([Parameter(Mandatory=$true)][string]$ApplicationRoot,[Parameter(Mandatory=$true)][string]$OutputPath)
$ErrorActionPreference='Stop'
Set-Location -LiteralPath $ApplicationRoot
. (Join-Path $ApplicationRoot 'engine/WinBookSplit.Runtime.ps1')
function HashText([string]$Text){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function SourceHashes { [ordered]@{Runtime=(Get-FileHash -LiteralPath (Join-Path $ApplicationRoot 'engine/WinBookSplit.Runtime.ps1') -Algorithm SHA256).Hash.ToLowerInvariant();Process=(Get-FileHash -LiteralPath (Join-Path $ApplicationRoot 'engine/WinBookSplit.Process.ps1') -Algorithm SHA256).Hash.ToLowerInvariant()} }
$hashesBefore=SourceHashes
$attempts=New-Object 'Collections.Generic.List[object]'
$registrations=@(Get-WinBookSplitRegisteredManagerPaths -ApplicationRoot $ApplicationRoot -Attempts $attempts -TimeoutSeconds 5 -WithRegistration)
if($registrations.Count -ne 1){throw ('Expected exactly one existing manager registration on this host; got '+$registrations.Count+'; attempts: '+($attempts | ConvertTo-Json -Depth 8 -Compress))}
$registration=$registrations[0]
$physical=Join-Path $registration.Package.InstallLocation 'pymanager.exe'
# Existing returned runtime from the early read-only list test is hashed for immutability only. It is never passed to application discovery/setup.
$observedRuntime=Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'Python/pythoncore-3.14-64/python.exe'
function Snapshot { [ordered]@{PathEnvironmentSha256=(HashText $env:PATH);ManagerPackage=$registration.Package.PackageFullName;ManagerExeSha256=(Get-FileHash -LiteralPath $physical -Algorithm SHA256).Hash.ToLowerInvariant();RuntimeVerificationOnlySha256=(Get-FileHash -LiteralPath $observedRuntime -Algorithm SHA256).Hash.ToLowerInvariant();AliasAttributes=[IO.File]::GetAttributes($registration.Path).ToString();AppVenvExists=[IO.Directory]::Exists((Join-Path $ApplicationRoot '.venv'))} }
$stateBefore=Snapshot
$listing=Invoke-WinBookSplitManagerListing -Registration $registration -ApplicationRoot $ApplicationRoot -TimeoutSeconds 5
$wrongPackage=Invoke-WinBookSplitProcess -Path $registration.Path -Arguments @('list','--format=exe') -WorkingDirectory $ApplicationRoot -TimeoutSeconds 5 -ExpectedPackageFullName ($registration.Package.PackageFullName+'-wrong') -ExpectedImagePath $physical
$wrongImage=Invoke-WinBookSplitProcess -Path $registration.Path -Arguments @('list','--format=exe') -WorkingDirectory $ApplicationRoot -TimeoutSeconds 5 -ExpectedPackageFullName $registration.Package.PackageFullName -ExpectedImagePath (Join-Path $registration.Package.InstallLocation 'py.exe')
$stateAfter=Snapshot
$checks=[ordered]@{RegistrationAccepted=($attempts.Count -eq 1 -and $attempts[0].Accepted);ListingExitZero=($listing.ExitCode -eq 0);ListingBound=$listing.PackageIdentityVerified;ListingJobAssigned=$listing.JobAssigned;ListingStopped=($listing.ParentStopped -and $listing.DescendantsStopped -and -not $listing.StopError);ListingComplete=($listing.StreamsComplete -and -not $listing.StreamError -and -not $listing.StdoutTruncated -and -not $listing.StderrTruncated);ListingPositiveControl=($listing.Stdout -match 'pythoncore-3\.14-64[\\/]python\.exe');WrongPackageRejected=(-not $wrongPackage.PackageIdentityVerified -and $wrongPackage.StartError -match 'does not match' -and [string]::IsNullOrEmpty($wrongPackage.Stdout));WrongPackageStopped=($wrongPackage.ParentStopped -and $wrongPackage.DescendantsStopped -and -not $wrongPackage.StopError);WrongImageRejected=(-not $wrongImage.PackageIdentityVerified -and $wrongImage.StartError -match 'does not match' -and [string]::IsNullOrEmpty($wrongImage.Stdout));WrongImageStopped=($wrongImage.ParentStopped -and $wrongImage.DescendantsStopped -and -not $wrongImage.StopError);StateUnchanged=(($stateBefore|ConvertTo-Json -Compress) -ceq ($stateAfter|ConvertTo-Json -Compress));SourceUnchangedDuringTest=(($hashesBefore|ConvertTo-Json -Compress) -ceq ((SourceHashes)|ConvertTo-Json -Compress))}
$record=[ordered]@{schema_version=1;kind='ACTUAL_WINDOWS11_PYTHONORG_COMPONENT_TEST';policy=[ordered]@{Process=(Get-ExecutionPolicy -Scope Process).ToString();Effective=(Get-ExecutionPolicy).ToString();Purpose='RemoteSigned component invocation; not MOTW acceptance'};host=[ordered]@{PowerShell=$PSVersionTable.PSVersion.ToString();Edition=$PSVersionTable.PSEdition;OS=[Environment]::OSVersion.VersionString;Process64Bit=[Environment]::Is64BitProcess};source=[ordered]@{Head=(& git rev-parse HEAD);Tree=(& git rev-parse 'HEAD^{tree}');WorktreeSourceHashes=$hashesBefore};commands=@('Get-WinBookSplitRegisteredManagerPaths -ApplicationRoot <WORKSPACE> -Attempts <LIST> -TimeoutSeconds 5 -WithRegistration','Invoke-WinBookSplitManagerListing -Registration <REAL_REGISTRATION> -ApplicationRoot <WORKSPACE> -TimeoutSeconds 5','Invoke-WinBookSplitProcess -Path <REAL_FAMILY_ALIAS> -Arguments list,--format=exe -WorkingDirectory <WORKSPACE> -TimeoutSeconds 5 -ExpectedPackageFullName <REAL_PACKAGE>-wrong -ExpectedImagePath <REAL_IMAGE>','Invoke-WinBookSplitProcess -Path <REAL_FAMILY_ALIAS> -Arguments list,--format=exe -WorkingDirectory <WORKSPACE> -TimeoutSeconds 5 -ExpectedPackageFullName <REAL_PACKAGE> -ExpectedImagePath <REAL_INSTALL_LOCATION>/py.exe');registration=$registration;registrationAttempts=$attempts;listing=$listing;wrongPackage=$wrongPackage;wrongImage=$wrongImage;stateBefore=$stateBefore;stateAfter=$stateAfter;checks=$checks;limitations=@('Windows11 python.org manager component test; not owner Windows10 Store gate.','No install/update, PATH/alias change, setup, venv creation, fallback acquisition or runtime injection occurred.','Manager list may write bounded local logs.','Wrong-binding children were rejected while suspended in source before ResumeThread; positive list output is the control.')}
$json=$record | ConvertTo-Json -Depth 15
$json=$json.Replace($env:USERPROFILE.Replace('\','\\'),'<USERPROFILE>').Replace($env:USERPROFILE,'<USERPROFILE>').Replace($ApplicationRoot.Replace('\','\\'),'<WORKSPACE>').Replace($ApplicationRoot,'<WORKSPACE>')
[IO.File]::WriteAllText($OutputPath,$json+"`n",(New-Object Text.UTF8Encoding($false)))
[ordered]@{Output=$OutputPath;Checks=$checks;AllPassed=(-not ($checks.Values -contains $false))} | ConvertTo-Json -Depth 4 -Compress
if($checks.Values -contains $false){exit 1}